/**
 * Generates the Billora app icons and the native splash logo from src/brand/mark.ts.
 *
 *   npm run brand
 *
 * Writes:
 *  - assets/brand/*.svg / *.png               master files (icon, store icon, splash logo)
 *  - android/app/src/main/res/mipmap-*        legacy + adaptive launcher icons (incl. themed/monochrome)
 *  - ios/Billora/Images.xcassets/AppIcon...   1024 × 1024 single-size app icon
 * The native splash itself is then generated by react-native-bootsplash from assets/brand/splash-logo.svg.
 */
import fs from 'node:fs';
import path from 'node:path';
import sharp from 'sharp';
import { MARK_COLORS, coin, markContent, receipt, receiptLines, slot, svgDoc, tile } from '../src/brand/mark.ts';

const root = path.resolve(import.meta.dirname, '..');
const out = (...p: string[]) => path.join(root, ...p);
const write = (file: string, data: string | Buffer) => {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, data);
  console.log('  ✓', path.relative(root, file));
};
/** Renders an SVG at exactly `size` px (density is scaled from the SVG's own width, so vectors stay sharp). */
const png = (svg: string, size: number) => {
  const width = Number(/width="([\d.]+)"/.exec(svg)?.[1] ?? size);
  return sharp(Buffer.from(svg), { density: (72 * size) / width }).resize(size, size).png().toBuffer();
};

/* ---------------- Masters ---------------- */
const iconSvg = svgDoc(markContent({ rounded: true }), 1024);
const squareSvg = svgDoc(markContent({ rounded: false }), 1024);
// Splash start frame: empty tile + printer slot. The JS splash then prints the receipt and drops the coin.
const splashSvg = svgDoc(tile() + slot(), 1024);

write(out('assets/brand/billora-icon.svg'), iconSvg);
write(out('assets/brand/splash-logo.svg'), splashSvg);
write(out('assets/brand/store-icon-512.png'), await png(squareSvg, 512));

/* ---------------- iOS ---------------- */
// Opaque and square: iOS applies its own rounded mask.
write(out('ios/Billora/Images.xcassets/AppIcon.appiconset/AppIcon-1024.png'), await sharp(await png(squareSvg, 1024)).flatten({ background: MARK_COLORS.base }).png().toBuffer());
write(
  out('ios/Billora/Images.xcassets/AppIcon.appiconset/Contents.json'),
  JSON.stringify(
    { images: [{ filename: 'AppIcon-1024.png', idiom: 'universal', platform: 'ios', size: '1024x1024' }], info: { author: 'xcode', version: 1 } },
    null,
    2,
  ) + '\n',
);

/* ---------------- Android ---------------- */
const densities: Record<string, number> = { mdpi: 1, hdpi: 1.5, xhdpi: 2, xxhdpi: 3, xxxhdpi: 4 };

// Adaptive icon (Android 8+): 108dp layers. The artwork is scaled so the B and the coin stay
// inside the 72dp circle that launcher masks keep visible (the coin just touches its edge).
const k = 0.68;
const offset = (108 - 100 * k) / 2;
const art = (inner: string) => `<g transform="translate(${offset} ${offset}) scale(${k})">${inner}</g>`;
const fgSvg = svgDoc(art(receipt() + receiptLines() + coin()), 108, '0 0 108 108');
const bgSvg = svgDoc(`<g transform="scale(1.08)"><rect width="100" height="100" fill="${MARK_COLORS.base}"/><path d="M0 0H100V34L0 86Z" fill="${MARK_COLORS.hi}"/></g>`, 108, '0 0 108 108');
// Themed icon (Android 13+): one colour, the launcher tints it. B silhouette + coin.
const monoSvg = svgDoc(art(receipt().replace(/fill="#[0-9A-Fa-f]{6}"/g, 'fill="#000"').replace('opacity="0.5"', 'opacity="0"') + coin().replace(/(fill|stroke)="#[0-9A-Fa-f]{6}"/g, '$1="#000"')), 108, '0 0 108 108');

for (const [name, scale] of Object.entries(densities)) {
  const dir = out(`android/app/src/main/res/mipmap-${name}`);
  const legacy = Math.round(48 * scale);
  const layer = Math.round(108 * scale);
  write(path.join(dir, 'ic_launcher.png'), await png(svgDoc(markContent({ rounded: true }), legacy), legacy));
  const circle = svgDoc(
    `<defs><clipPath id="c"><circle cx="50" cy="50" r="50"/></clipPath></defs><g clip-path="url(#c)">${markContent({ rounded: false })}</g>`,
    legacy,
  );
  write(path.join(dir, 'ic_launcher_round.png'), await png(circle, legacy));
  write(path.join(dir, 'ic_launcher_foreground.png'), await png(fgSvg, layer));
  write(path.join(dir, 'ic_launcher_background.png'), await png(bgSvg, layer));
  write(path.join(dir, 'ic_launcher_monochrome.png'), await png(monoSvg, layer));
}

const adaptive = `<?xml version="1.0" encoding="utf-8"?>
<adaptive-icon xmlns:android="http://schemas.android.com/apk/res/android">
    <background android:drawable="@mipmap/ic_launcher_background" />
    <foreground android:drawable="@mipmap/ic_launcher_foreground" />
    <monochrome android:drawable="@mipmap/ic_launcher_monochrome" />
</adaptive-icon>
`;
write(out('android/app/src/main/res/mipmap-anydpi-v26/ic_launcher.xml'), adaptive);
write(out('android/app/src/main/res/mipmap-anydpi-v26/ic_launcher_round.xml'), adaptive);

console.log('\nDone. Next: the native splash is generated with\n  npx react-native-bootsplash generate assets/brand/splash-logo.svg --platforms=android,ios --background=F5F6F3 --logo-width=120');
